using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace UltimateWinUI.Models;

/// <summary>Root of Assets/tweaks.json, generated by tools/catalog_gen.py.</summary>
public sealed class CatalogDoc
{
    [JsonPropertyName("library")] public string Library { get; set; } = "";
    [JsonPropertyName("source")] public string Source { get; set; } = "";
    [JsonPropertyName("license")] public string License { get; set; } = "";
    [JsonPropertyName("categories")] public List<Category> Categories { get; set; } = new();
}

public sealed class Category
{
    [JsonPropertyName("name")] public string Name { get; set; } = "";
    [JsonPropertyName("folder")] public string Folder { get; set; } = "";
    [JsonPropertyName("description")] public string Description { get; set; } = "";
    [JsonPropertyName("tweaks")] public List<Tweak> Tweaks { get; set; } = new();

    [JsonIgnore] public string IconGlyph => Name switch
    {
        "Check" => "\uE90F",
        "Refresh" => "\uE72C",
        "Setup" => "\uE713",
        "Installers" => "\uE896",
        "Graphics" => "\uE7F4",
        "Windows" => "\uE770",
        "Hardware" => "\uE772",
        "Advanced" => "\uE7BA",
        _ => "\uE8A5",
    };
}

public sealed class Tweak
{
    [JsonPropertyName("id")] public string Id { get; set; } = "";
    [JsonPropertyName("name")] public string Name { get; set; } = "";
    [JsonPropertyName("description")] public string Description { get; set; } = "";
    [JsonPropertyName("order")] public int Order { get; set; }
    [JsonPropertyName("script")] public string Script { get; set; } = "";
    /// <summary>toggle | dropdown | button | actions</summary>
    [JsonPropertyName("control")] public string Control { get; set; } = "button";
    [JsonPropertyName("options")] public List<TweakOption> Options { get; set; } = new();
    [JsonPropertyName("recommended")] public string? Recommended { get; set; }
    [JsonPropertyName("risk")] public string? Risk { get; set; }

    // Runtime state, not serialized from the catalog.
    [JsonIgnore] public Category? Parent { get; set; }
    [JsonIgnore] public string? CurrentOptionLabel { get; set; }
    [JsonIgnore] public StateSource CurrentSource { get; set; } = StateSource.Unknown;
    [JsonIgnore] public bool IsBusy { get; set; }

    [JsonIgnore]
    public string StatusText => CurrentSource switch
    {
        StateSource.Detected => $"Detected: {CurrentOptionLabel}",
        StateSource.Applied => $"Last applied: {CurrentOptionLabel}",
        _ => "State unknown",
    };

    /// <summary>Options the user picks between (excludes check actions).</summary>
    [JsonIgnore]
    public List<TweakOption> ChoiceOptions
    {
        get
        {
            var list = new List<TweakOption>();
            foreach (var o in Options)
                if (o.Kind == "apply" || o.Kind == "launch")
                    list.Add(o);
            return list;
        }
    }

    [JsonIgnore]
    public TweakOption? CheckOption
    {
        get
        {
            foreach (var o in Options)
                if (o.Kind == "check")
                    return o;
            return null;
        }
    }

    /// <summary>
    /// The option that counts as "on" for a toggle: the recommended one when the
    /// library marks one, otherwise the first choice.
    /// </summary>
    [JsonIgnore]
    public TweakOption? ActiveOption
    {
        get
        {
            var choices = ChoiceOptions;
            if (choices.Count == 0) return null;
            if (Recommended != null)
                foreach (var o in choices)
                    if (o.Label == Recommended)
                        return o;
            return choices[0];
        }
    }
}

public sealed class TweakOption
{
    [JsonPropertyName("label")] public string Label { get; set; } = "";
    /// <summary>apply | check | launch</summary>
    [JsonPropertyName("kind")] public string Kind { get; set; } = "apply";
    [JsonPropertyName("target")] public string? Target { get; set; }
    [JsonPropertyName("body")] public string Body { get; set; } = "";
    /// <summary>Body variant with native ARM64 payloads, used automatically on ARM64.</summary>
    [JsonPropertyName("arm64Body")] public string? Arm64Body { get; set; }
    [JsonPropertyName("signature")] public List<SigEntry>? Signature { get; set; }
    [JsonPropertyName("deletes")] public List<SigEntry>? Deletes { get; set; }
    /// <summary>Prompts for values the script asks via Read-Host (fed through stdin).</summary>
    [JsonPropertyName("inputs")] public List<string>? Inputs { get; set; }
    /// <summary>Extra script output or interaction to review before running.</summary>
    [JsonPropertyName("confirmation")] public string? ConfirmationMessage { get; set; }
}

/// <summary>One registry value an option writes; used for live state detection.</summary>
public sealed class SigEntry
{
    [JsonPropertyName("key")] public string Key { get; set; } = "";
    [JsonPropertyName("name")] public string Name { get; set; } = "";
    [JsonPropertyName("value")] public object? Value { get; set; }
    /// <summary>dword | qword | string | binary | deleted</summary>
    [JsonPropertyName("kind")] public string Kind { get; set; } = "dword";
}

public enum StateSource
{
    Unknown,
    Detected,
    Applied,
}
